import{_ as n,l as o,o as e,c as s,v as t,p as l,x as i,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"模运算与同余","description":"","frontmatter":{"title":"模运算与同余","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/modular-arithmetic.md","filePath":"cs/modular-arithmetic.md","lastUpdated":1789023840000}'),m={name:"cs/modular-arithmetic.md"};function c(b,a,u,_,f,q){const r=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="模运算与同余" tabindex="-1">模运算与同余 <a class="header-anchor" href="#模运算与同余" aria-label="Permalink to &quot;模运算与同余&quot;">​</a></h1><div class="epigraph"><p>$a\\equiv b\\pmod n$ 当 $n$ 整除 $a-b$；剩余类做成环 $\\mathbb{Z}/n\\mathbb{Z}$。密码学的加减乘都在这一层上，尚未求逆。</p><footer>—— 据 Gauss, Disquisitiones Arithmeticae；Knuth, TAOCP 卷 2 整理</footer></div><p>信息单元在<a href="/cs/max-entropy-principle">最大熵</a> 结束。本单元是「密码学要用的那一层」，不是协议课。主干<a href="/cs/symmetric-crypto">对称密码</a>、<a href="/cs/diffie-hellman-paper">DH</a> 已经用过模幂，从未把同余写严。缺口从 <strong>\\(a\\bmod n\\) 与剩余类</strong>起。后课默认已读完本课的算术。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>整数除法余数：代表元取 \\(\\{0,\\ldots,n-1\\}\\)。同余是等价关系，兼容加乘：可在类上定义运算。\\(\\mathbb{Z}/n\\mathbb{Z}\\) 是环：有 \\(0,1\\)，加可逆，乘未必。\\(n\\) 合数时有零因子（\\(2\\cdot 3\\equiv 0\\pmod 6\\)），不能随意「两边同除」。本课不求乘逆——下一课扩展欧几里得。</p><p>计算机的机器字是 \\(n=2^{w}\\) 的特殊情形；补码课已用，这里 \\(n\\) 任意。</p><h3 id="同余不是「余数相等」的口语" tabindex="-1">同余不是「余数相等」的口语 <a class="header-anchor" href="#同余不是「余数相等」的口语" aria-label="Permalink to &quot;同余不是「余数相等」的口语&quot;">​</a></h3><p>负元：\\(-1\\equiv n-1\\)。编程语言的 <code>%</code> 对负数实现不一，数学上 \\(n\\mathbb{Z}\\) 陪集明确。不要把浮点取模当定理。</p><p><span class="marginnote">Gauss 的同余记号。Knuth 卷 2 讨论表示与快速幂。本课快速幂只点名：平方乘，后课欧拉定理才减指数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>验证加乘良定义。写 \\((\\mathbb{Z}/n\\mathbb{Z})^\\times\\) 为与 \\(n\\) 互素的类——群结构后课。举 \\(n=15\\) 看零因子。强调：方程 \\(ax\\equiv b\\) 何时有解，下一课 gcd。</p>',11)),(e(),l(p,null,{default:i(()=>[h(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E6%95%B4%E6%95%B0%20Z%22%5D%20--%3E%20CONG%5B%22%E6%A8%A1%20n%20%E5%90%8C%E4%BD%99%22%5D%0A%20%20CONG%20--%3E%20RING%5B%22%E7%8E%AF%20Z%2FnZ%22%5D%0A%20%20RING%20--%3E%20LATER%5B%22%E9%80%86%E3%80%81%CF%86(n)%E3%80%81CRT%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>公钥课的对象（RSA 模 \\(n=pq\\)、DH 模 \\(p\\)）都是这个环或它的乘法群。本单元按需加结构，不在第一课上椭圆曲线。与<a href="/cs/boolean-algebra">布尔代数</a> 对照：\\(n=2\\) 时剩余类可当比特运算，但本课 \\(+\\) 是模加，不是或。</p><p>快速幂平方乘：\\(O(\\log e)\\) 次模乘算 \\(a^e\\bmod n\\)，后课欧拉再把 \\(e\\) 先约到 \\(\\varphi(n)\\)。表示：大整数用 \\(2^{32}\\) 或 \\(2^{64}\\) 字，与理论无关。\\(n=1\\) 退化；密码模数奇数。本课加法逆永远存在（\\(n-a\\)），乘法逆下一课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证唯一分解，不引入理想。不写 RSA。后课默认：谈到模运算，即剩余类环上的 \\(+\\)、\\(\\cdot\\)。下一课 gcd 与逆。</p><p>剩余类环上加永远可逆，乘不一定。后课所有公钥算术都先落在这一层，再决定是当域还是当合数环。不要把机器字溢出当成一般 \\(n\\) 的定理。</p><p>上一课留下的缺口在本课收口；「模运算与同余」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>同余是等价关系；\\(\\mathbb{Z}/n\\mathbb{Z}\\) 是环。</li><li>合数模有零因子，不能随意约分。</li><li>协议课已用过；本课把算术钉严。</li><li>后课求逆、\\(\\varphi(n)\\)、CRT 都默认本课的剩余类。</li><li>出处：Gauss, <em>Disquisitiones</em>；Knuth, TAOCP 卷 2。</li></ul>',9))])}const E=n(m,[["render",c]]);export{T as __pageData,E as default};
